using System.Text.RegularExpressions;

/// <summary>
/// Validate route in extract and finalization screen helper
/// </summary>
class METValidateRouteHelper
{



}

Method.Source:
/// <summary>
/// validate route value for upper case
/// </summary>
/// <param name = "_routeValue">Route value</param>
/// <returns>True if upper case else false</returns>
public boolean validateRouteForUpperCase(str _routeValue)
{
    int i;
    int stringLength = strLen(_routeValue);
    str character;
    boolean ret = true;

    for (i=1; i<=stringLength; i+=1)
    {
        character = subStr(_routeValue, i, 1);
        //If the character is NOT EQUAL to it's lowercase counterpart, it must be uppercase:
        if (char2num(_routeValue, i) != char2num(strUpr(_routeValue), i))
        {
            ret = checkFailed("@MET:InvalidFormat4DigitLowerCaseAlphaNumericRoute");
        }
    }

    return ret;
}

/// <summary>
/// Validate route for alphanumeric
/// </summary>
/// <param name = "_route">Route value</param>
/// <returns>true if it is alphanumeric or else false</returns>
public boolean validateForAlphaNumeric(str _route)
{
    boolean ret = true;


    if (!Regex::IsMatch(_route, METConstants::RoutePattern))
    {
        ret = checkFailed("@MET:InvalidFormat4DigitAlphaNumericRoute");
    }

    return ret;
}

/// <summary>
/// validate route length
/// </summary>
/// <param name = "_lenRoute">route length</param>
/// <returns>true if it length is greater than  4 or else false</returns>
public boolean validateRouteLength(int _lenRoute)
{
    boolean ret = true;

    if (_lenRoute < 4)
    {
        ret = checkFailed("@MET:InvalidFormat4DigitAlphaNumericRoute");
    }

    return ret;
}

/// <summary>
/// validate route stop length
/// </summary>
/// <param name = "_routeStopNum">route stop num</param>
/// <param name = "_lenRouteStop">route stop length</param>
/// <returns>true if it length is greater than  2 or else false</returns>
public boolean validateRouteStop(int _routeStopNum, int _lenRouteStop)
{
    boolean ret = true;

    if (_routeStopNum < 0 || _routeStopNum > 99 || _lenRouteStop > 2)
    {
        ret = checkFailed("@MET:InvalidFormatRouteStop99");
    }

    return ret;
}
